import urllib.request,concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/'+p for p in ['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','MonteCarlo_common.h','CMakeLists.txt','README.md']]+['README.md']
def get(p):
